<template><div><div class="admin-page-head"><div><h1>{{ form.id ? 'Редактирование статьи' : 'Новая статья' }}</h1><p>Публикация контента напрямую из админки Trove.</p></div><NuxtLink class="btn" to="/admin/guides">← Все статьи</NuxtLink></div><div class="editor"><section class="admin-card"><div class="field"><label>Название</label><input v-model="form.title" class="input" style="width:100%;box-sizing:border-box"></div><div class="field"><label>Slug</label><input v-model="form.slug" class="input" style="width:100%;box-sizing:border-box"></div><div class="field"><label>Краткое описание</label><textarea v-model="form.excerpt" class="textarea" style="min-height:110px"></textarea></div><div class="field"><div class="editor-tabs"><button :class="{active:tab==='write'}" @click="tab='write'">Текст</button><button :class="{active:tab==='preview'}" @click="tab='preview'">Предпросмотр</button></div><textarea v-if="tab==='write'" v-model="form.content" class="textarea" placeholder="Используй Markdown: ## Заголовок, **жирный**, - список, [ссылка](https://…)"></textarea><article v-else class="article-preview"><h2>{{ form.title || 'Без названия' }}</h2><p v-if="form.excerpt" class="preview-excerpt">{{ form.excerpt }}</p><div v-for="(block,i) in previewBlocks" :key="i" class="preview-block"><h3 v-if="block.type==='h2'">{{ block.text }}</h3><h4 v-else-if="block.type==='h3'">{{ block.text }}</h4><p v-else>{{ block.text }}</p></div></article></div></section><aside class="admin-card"><div class="field"><label>Статус</label><select v-model="form.status" class="select"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></div><div class="field"><label>Обложка URL</label><input v-model="form.coverUrl" class="input"></div><div class="field"><label>SEO title</label><input v-model="form.seoTitle" class="input"></div><div class="field"><label>SEO description</label><textarea v-model="form.seoDescription" class="textarea" style="min-height:120px"></textarea></div><div class="actions"><button class="btn" v-if="form.id" @click="remove">Удалить</button><button class="btn primary" @click="save">{{ saving?'Сохраняем…':'Сохранить' }}</button></div><p v-if="error" class="muted">{{ error }}</p></aside></div></div></template>
<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'});const api=useApi();const route=useRoute();const tab=ref<'write'|'preview'>('write');const saving=ref(false);const error=ref('');const form=reactive<any>({id:'',slug:'',title:'',excerpt:'',coverUrl:'',content:'',status:'draft',seoTitle:'',seoDescription:''});if(route.params.id!=='new'){const r=await api<any>(`/api/admin/guides/${route.params.id}`);Object.assign(form,{id:r.item.id,slug:r.item.slug,title:r.item.title,excerpt:r.item.excerpt,coverUrl:r.item.cover_url||'',content:r.item.content,status:r.item.status,seoTitle:r.item.seo_title||'',seoDescription:r.item.seo_description||''})}const previewBlocks=computed(()=>String(form.content||'').split(/\n+/).filter(Boolean).map((text:string)=>{const clean=text.replace(/^###\s*/, '').replace(/^##\s*/, '');return {type:text.startsWith('### ')?'h3':text.startsWith('## ')?'h2':'p',text:clean.replace(/\*\*(.*?)\*\*/g,'$1')}}))
const save=async()=>{saving.value=true;error.value='';try{const r=await api<any>('/api/admin/guides',{method:'POST',body:form});Object.assign(form,{id:r.item.id});if(route.params.id==='new')await navigateTo(`/admin/guides/${r.item.id}`)}catch(e:any){error.value=e?.data?.error||'Не удалось сохранить'}finally{saving.value=false}};const remove=async()=>{if(!confirm('Удалить статью?'))return;await api(`/api/admin/guides/${form.id}`,{method:'DELETE'});await navigateTo('/admin/guides')}
</script>
<style scoped>.editor-tabs{display:flex;gap:4px;margin-bottom:10px;border-bottom:1px solid #edf0f4}.editor-tabs button{border:0;background:transparent;padding:8px 12px;color:#7a8596;cursor:pointer}.editor-tabs button.active{color:#172033;font-weight:700;border-bottom:2px solid #172033}.article-preview{min-height:460px;padding:12px 4px}.article-preview h2{font-size:30px;letter-spacing:-.03em;margin:0 0 12px}.article-preview h3{font-size:21px;margin:26px 0 8px}.article-preview h4{font-size:16px;margin:20px 0 6px}.article-preview p{line-height:1.7;color:#4e596a}.preview-excerpt{font-size:16px!important;color:#7a8596!important}</style>
